INSERT INTO fut_evolution_log VALUES(9,25,2489,'Repeat Delivery',4,'2026-09-19','2026-09-19',78,78,NULL,'{"PAC": 78, "SHO": 65, "PAS": 76, "DRI": 75, "DEF": 34, "PHY": 64}',NULL,NULL,NULL,NULL,'fut.gg GG Club 싱크(2026-09-19) — 아이템 반복 접미 -3 · PAS 73→76 · DRI 74→75','MEASURED — EA 싱크 실측. 4단계 보상(스킬무브 +2★·가속·민첩·드리블)과 방향 일치','반복 배급 4단계(최종) — 싱크 실측으로 확인. 스킬무브 +2★·프리킥 정확도+4·가속+5·민첩성+8·드리블+8',0);
INSERT INTO fut_evolution_log VALUES(10,25,2489,'Repeat Delivery',4,'2026-09-20','2026-09-20',78,78,'{"PAC": 80, "SHO": 65, "PAS": 76, "DRI": 75, "DEF": 34, "PHY": 64}','{"PAC":80,"SHO":65,"PAS":76,"DRI":75,"DEF":34,"PHY":64}',NULL,NULL,NULL,NULL,'scripts/fut_club.py evolve (2026-09-20 기록) · 적용 후 값 출처: 사용자 입력값','MEASURED(사용자 행위) — 적용 사실은 사용자 보고. 적용 후 스탯은 사용자 입력값.','반복 배급 1회차 **최종(4/4) 완주** — 2026-09-20 GG Club 싱크 실측(아이템 접미 -4). ⭐ 4단계 보상의 가속+5가 이제 반영됐다: PAC 78→80(PAC=가속.45+질주.55 구성식과 정합). ⚠️ 정정: 09-19에 기록한 level 4 행(log #9, 접미 -3)은 실제로는 **3단계**였다 — 그때 오른 것은 PAS 73→76·DRI 74→75로 3단계 보상(볼컨트롤+8·크로스+10·커브+12)과 일치한다. ⇒ **접미 -N = N단계 완료**가 맞는 대응이다. 카탈로그상 2489는 4단계·repeatability 2이므로 Alysson은 이제 1회차를 닫았고 2회차가 가능하다.',0);
INSERT INTO fut_evolution_log VALUES(11,30,2492,'Intro to Repeatable Evolutions',1,'2026-09-20','2026-09-20',67,67,'{"PAC": 70, "SHO": 68, "PAS": 54, "DRI": 62, "DEF": 22, "PHY": 74}','{"PAC":70,"SHO":68,"PAS":54,"DRI":62,"DEF":22,"PHY":74}',NULL,NULL,NULL,NULL,'scripts/fut_club.py evolve (2026-09-20 기록) · 적용 후 값 출처: 사용자 입력값','MEASURED(사용자 행위) — 적용 사실은 사용자 보고. 적용 후 스탯은 사용자 입력값.','반복 가능 진화 소개 **2회차**(사용자 확인 「2번 돌린거야」) — 아이템 접미 -1 → -2 · OVR 66→67. ⭐ 1회차와 같은 **1단계 보상(Overall +1)**이 다시 들어온 것이라 2회차 1단계로 기록한다(2단계 보상에는 Overall 상승이 없다 — 슛파워+3·발리+3·FK+4·롱패스+4·드리블+4). 카탈로그 repeatability=2와 정합하며 이로써 **이 진화는 소진**됐다.',0);
INSERT INTO fut_evolution_log VALUES(12,146,2489,'Repeat Delivery',1,'2026-09-20',NULL,73,73,'{"PAC": 82, "SHO": 60, "PAS": 70, "DRI": 68, "DEF": 40, "PHY": 61}','{"PAC":82,"SHO":60,"PAS":70,"DRI":68,"DEF":40,"PHY":61}',NULL,NULL,NULL,NULL,'scripts/fut_club.py evolve (2026-09-20 기록) · 적용 후 값 출처: 사용자 입력값','MEASURED(사용자 행위) — 적용 사실은 사용자 보고. 적용 후 스탯은 사용자 입력값.','반복 배급(Repeat Delivery) **시작** — 사용자 보고 「알리송이 했던 진화 시작」(2026-09-20). 완주 시 1단계 OVR+8(73→81 예상) · 질주+5 · 침착+10 · 균형+12 · 짧은패스+15. ⚠️ 진행 중이라 **스탯은 현재값 그대로** 둔다(--in-progress) — 완주 시 complete로 반영한다. ⛔ fut.gg는 진화 경로를 주지 않으므로 이 귀속은 **사용자 보고**가 유일 근거다. ⭐ 이 카드는 2026-09-20 3,700코인 입수 신규분이고 선발 스쿼드에 들어 있다.',0);
